{"concept":"Transform YouTube into the clockwork, parchment, and bronze-geared mechanical map of Westeros from the Game of Thrones intro.","fingerprint":"Medieval parchment, brass astrolabe, gothic serif, grid","architecture":"restyle","needsHud":false,"hudReason":"","id":"8f7c446e3ea7","name":"Westeros Astrolabe Feed","dark":true,"bg":"#2b1f14","surface":"#3d2e1e","surface2":"#523c24","fg":"#d6c299","ink":"#1a120b","accent":"#8c2d19","remapSurfaces":false,"customCss":"@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@600;700;900&display=swap');

@keyframes spinGearSlow {
 from { transform: rotate(0deg); }
 to { transform: rotate(360deg); }
}
@keyframes spinGearRev {
 from { transform: rotate(360deg); }
 to { transform: rotate(0deg); }
}
@keyframes sigilPulse {
 0%, 100% { filter: drop-shadow(0 0 2px rgba(140, 45, 25, 0.4)); }
 50% { filter: drop-shadow(0 0 8px rgba(214, 194, 153, 0.6)); }
}

html, body {
 background-color: #2b1f14 !important;
 color: #d6c299 !important;
 font-family: 'Cinzel', 'Trajan Pro', Georgia, serif !important;
 letter-spacing: 0.05em !important;
 min-height: 100vh !important;
}

/* Top Navigation Bar as Bronze Astrolabe Header */
header, ytm-mobile-topbar-renderer, ytm-header-bar {
 background: linear-gradient(180deg, #3d2e1e 0%, #2b1f14 100%) !important;
 border-bottom: 2px solid #8c2d19 !important;
 box-shadow: 0 4px 18px rgba(0, 0, 0, 0.8), inset 0 -1px 0 #523c24 !important;
 position: sticky !important;
 top: 0 !important;
 z-index: 9999 !important;
}

/* Ancient Ledger Search Field */
ytm-searchbox, form, input[type="search"], input.search-input {
 background: #d6c299 !important;
 color: #1a120b !important;
 font-family: 'Cinzel', serif !important;
 font-weight: 700 !important;
 letter-spacing: 0.08em !important;
 border: 1px solid #523c24 !important;
 border-radius: 2px !important;
 box-shadow: inset 0 2px 5px rgba(43, 31, 20, 0.5) !important;
}
input[type="search"]::placeholder, input.search-input::placeholder {
 color: #523c24 !important;
 text-transform: uppercase !important;
}

/* Main Content Stream & Multi-column Grid Layout */
lazy-list, .feed-container, #app {
 display: grid !important;
 grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr)) !important;
 gap: 16px !important;
 width: 100% !important;
 max-width: 100% !important;
 box-sizing: border-box !important;
 padding: 12px !important;
 background: transparent !important;
}

/* Castle Keep Mechanical Unit Cards */
ytm-video-with-context-renderer.item.adaptive-feed-item,
div.ytGridShelfViewModelGridShelfItem,
ytm-shorts-lockup-view-model.shortsLockupViewModelHost {
 background: radial-gradient(circle at 50% 30%, #3d2e1e 0%, #2b1f14 100%) !important;
 border: 2px solid #8c2d19 !important;
 border-radius: 4px !important;
 box-shadow: inset 0 0 20px rgba(0, 0, 0, 0.85), 0 6px 14px rgba(0, 0, 0, 0.7) !important;
 display: flex !important;
 flex-direction: column !important;
 align-items: stretch !important;
 box-sizing: border-box !important;
 width: 100% !important;
 max-width: 100% !important;
 min-width: 0 !important;
 margin: 0 !important;
 padding: 10px !important;
 position: relative !important;
 overflow: hidden !important;
 transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease !important;
}

/* Mechanical touch clink response */
ytm-video-with-context-renderer.item.adaptive-feed-item:active,
div.ytGridShelfViewModelGridShelfItem:active {
 transform: scale(0.98) !important;
 border-color: #d6c299 !important;
 box-shadow: inset 0 0 15px rgba(140, 45, 25, 0.8), 0 0 12px rgba(214, 194, 153, 0.5) !important;
}

/* Internal Row Restructuring to Stacking Cards */
ytm-media-item {
 display: flex !important;
 flex-direction: column !important;
 width: 100% !important;
 max-width: 100% !important;
 margin: 0 !important;
}

/* Media Preview Framed in Cast Bronze */
ytm-thumbnail-cover, .media-item-thumbnail-container, img.video-thumbnail, ytm-thumbnail-overlay-time-status-renderer {
 border: 1px solid #523c24 !important;
 border-radius: 2px !important;
 box-shadow: 0 2px 8px rgba(0, 0, 0, 0.9) !important;
 width: 100% !important;
 position: relative !important;
}

/* Mechanical Gear Corner Sigils via Pseudo-elements */
ytm-video-with-context-renderer.item.adaptive-feed-item::before {
 content: '' !important;
 position: absolute !important;
 top: -12px !important;
 right: -12px !important;
 width: 32px !important;
 height: 32px !important;
 border: 2px dashed #8c2d19 !important;
 border-radius: 50% !important;
 opacity: 0.45 !important;
 animation: spinGearSlow 18s linear infinite !important;
 pointer-events: none !important;
}

ytm-video-with-context-renderer.item.adaptive-feed-item::after {
 content: '' !important;
 position: absolute !important;
 bottom: -8px !important;
 left: -8px !important;
 width: 24px !important;
 height: 24px !important;
 border: 2px dotted #523c24 !important;
 border-radius: 50% !important;
 opacity: 0.35 !important;
 animation: spinGearRev 12s linear infinite !important;
 pointer-events: none !important;
}

/* Weathered Medieval Serif Typography */
h1, h2, h3, .media-item-headline, .compact-media-item-headline {
 font-family: 'Cinzel', 'Trajan Pro', Georgia, serif !important;
 font-size: clamp(0.75rem, 2vw, 1rem) !important;
 font-weight: 700 !important;
 text-transform: uppercase !important;
 letter-spacing: 0.12em !important;
 color: #d6c299 !important;
 line-height: 1.35 !important;
 margin-top: 8px !important;
 white-space: normal !important;
 -webkit-line-clamp: unset !important;
 max-height: none !important;
 height: auto !important;
 text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.9) !important;
}

/* Secondary Details & Metadata */
.media-item-details, .subhead, .compact-media-item-stats, span, p {
 color: #a4916e !important;
 font-family: 'Cinzel', serif !important;
 font-size: clamp(0.65rem, 1.6vw, 0.8rem) !important;
 letter-spacing: 0.06em !important;
}

/* Button and Badge Accents */
button, .yt-spec-button-shape-next--tonal {
 background: #523c24 !important;
 color: #d6c299 !important;
 border: 1px solid #8c2d19 !important;
 border-radius: 2px !important;
 font-family: 'Cinzel', serif !important;
 text-transform: uppercase !important;
 letter-spacing: 0.1em !important;
}

/* Continuation Elements and Infinite Sentinel */
ytm-continuation-item-renderer, [role="progressbar"] {
 grid-column: 1 / -1 !important;
 display: flex !important;
 justify-content: center !important;
 padding: 16px !important;
 color: #d6c299 !important;
}","backdropHtml":"<div style="position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:-1;background:radial-gradient(ellipse at 50% 50%, rgba(61,46,30,0.5) 0%, rgba(43,31,20,0.95) 100%);"><svg width="100%" height="100%" xmlns="http://www.w3.org/2000/svg" opacity="0.12"><defs><pattern id="topo" width="120" height="120" patternUnits="userSpaceOnUse"><circle cx="60" cy="60" r="50" fill="none" stroke="#d6c299" stroke-width="1" stroke-dasharray="4,3"/><circle cx="60" cy="60" r="35" fill="none" stroke="#8c2d19" stroke-width="1.2"/><circle cx="60" cy="60" r="15" fill="none" stroke="#d6c299" stroke-width="0.8"/><path d="M0,60 H120 M60,0 V120" stroke="#523c24" stroke-width="0.6"/></pattern></defs><rect width="100%" height="100%" fill="url(#topo)"/></svg></div>","hudHtml":"","customJs":"if (window.MydesBridge && typeof MydesBridge.enable3DTilt === 'function') { MydesBridge.enable3DTilt(0.75); }"}

{"concept":"Transform YouTube into a rain-slicked, blood-stained Gotham underworld straight out of Matt Reeves' The Batman.","fingerprint":"industrial gritty dark red gothic grid","architecture":"restyle","needsHud":false,"hudReason":"","id":"ee361bf70348","name":"Gotham Vengeance","dark":true,"bg":"#050505","surface":"#0a0a0c","surface2":"#141113","fg":"#d0c8c5","ink":"#ff2a2a","accent":"#8b0000","remapSurfaces":false,"customCss":"@keyframes pulse-bat { 0%, 100% { box-shadow: inset 0 0 20px rgba(139,0,0,0.6), 0 0 15px rgba(0,0,0,0.9); border-color: rgba(139,0,0,0.5); } 50% { box-shadow: inset 0 0 40px rgba(180,0,0,0.9), 0 0 25px rgba(139,0,0,0.8); border-color: rgba(220,20,60,0.8); } }
@keyframes blood-drip { 0% { transform: translateY(-100%); } 100% { transform: translateY(100vh); } }

html, body {
 background-color: #050505 !important;
 color: #d0c8c5 !important;
 font-family: 'Special Elite', 'Courier New', monospace !important;
 letter-spacing: 1px !important;
 overflow-x: hidden !important;
}

header, ytm-mobile-topbar-renderer, .mobile-topbar-header {
 background: #030303 !important;
 border-bottom: 2px solid #8b0000 !important;
 box-shadow: 0 4px 20px rgba(139,0,0,0.5) !important;
 padding-block: clamp(8px, 2vw, 14px) !important;
 position: sticky !important;
 top: 0 !important;
 z-index: 9999 !important;
}

input, input.cbox, .search-bar input {
 background: #0c0a0a !important;
 border: 1px solid #5a0000 !important;
 color: #ff3b3b !important;
 border-radius: 2px !important;
 font-family: 'Special Elite', 'Courier New', monospace !important;
 padding: clamp(6px, 1.5vw, 10px) !important;
 text-shadow: 0 0 5px rgba(255,0,0,0.6) !important;
}

lazy-list, div.ytGridShelfViewModelGridShelfRow {
 display: grid !important;
 grid-template-columns: repeat(auto-fit, minmax(min(100%, max(140px, 42vw)), 1fr)) !important;
 gap: clamp(10px, 2.5vw, 18px) !important;
 padding-inline: clamp(8px, 2vw, 16px) !important;
 padding-block: clamp(10px, 2.5vw, 20px) !important;
 width: 100% !important;
 max-width: 100% !important;
 box-sizing: border-box !important;
}

ytm-video-with-context-renderer.item.adaptive-feed-item,
div.ytGridShelfViewModelGridShelfItem,
ytm-shorts-lockup-view-model.shortsLockupViewModelHost {
 display: flex !important;
 flex-direction: column !important;
 align-items: stretch !important;
 width: 100% !important;
 max-width: 100% !important;
 min-width: 0 !important;
 box-sizing: border-box !important;
 background: #0a0a0c !important;
 border: 1px solid rgba(139,0,0,0.4) !important;
 border-radius: 4px !important;
 clip-path: polygon(0 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%) !important;
 padding: clamp(8px, 1.8vw, 12px) !important;
 box-shadow: 0 8px 32px rgba(0,0,0,0.95), inset 0 0 15px rgba(139,0,0,0.2) !important;
 transition: transform 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease !important;
 animation: pulse-bat 6s infinite alternate !important;
}

ytm-video-with-context-renderer.item.adaptive-feed-item:active,
div.ytGridShelfViewModelGridShelfItem:active {
 transform: scale(0.97) !important;
 border-color: #ff0000 !important;
 box-shadow: 0 0 25px rgba(255,0,0,0.7), inset 0 0 20px rgba(255,0,0,0.4) !important;
}

ytm-media-item.big-shorts-singleton {
 display: flex !important;
 flex-direction: column !important;
 width: 100% !important;
 min-width: 0 !important;
}

div.media-item-details, .details {
 width: 100% !important;
 max-width: 100% !important;
 min-width: 0 !important;
 padding: 8px 0 0 0 !important;
 box-sizing: border-box !important;
}

h3, .media-item-headline, .compact-media-item-headline {
 color: #e6dfdd !important;
 font-family: 'Special Elite', 'Courier New', monospace !important;
 font-weight: 700 !important;
 text-transform: uppercase !important;
 font-size: clamp(0.85rem, 2.5vw, 1.05rem) !important;
 text-shadow: 0 0 8px rgba(139,0,0,0.8), 0 0 2px rgba(255,50,50,0.6) !important;
 line-height: 1.35 !important;
 white-space: normal !important;
 overflow-wrap: anywhere !important;
 -webkit-line-clamp: unset !important;
 max-height: none !important;
 height: auto !important;
}

img, video, .video-thumbnail-container-compact {
 filter: contrast(130%) brightness(85%) saturate(70%) sepia(30%) drop-shadow(0 0 4px rgba(0,0,0,0.8)) !important;
 border-radius: 2px !important;
 border: 1px solid rgba(139,0,0,0.3) !important;
 width: 100% !important;
 height: auto !important;
 max-width: 100% !important;
 position: static !important;
}

.subhead, .media-channel, [class*="metadata"] {
 color: #8c827a !important;
 font-size: clamp(0.7rem, 2vw, 0.8rem) !important;
 text-transform: uppercase !important;
 letter-spacing: 1px !important;
}

button, .yt-spec-button-shape-next {
 background: #141113 !important;
 color: #ff3b3b !important;
 border: 1px solid rgba(139,0,0,0.6) !important;
 border-radius: 2px !important;
 text-transform: uppercase !important;
 font-family: 'Special Elite', monospace !important;
 letter-spacing: 1px !important;
}

button:active, .yt-spec-button-shape-next:active {
 background: #8b0000 !important;
 color: #000000 !important;
}
/* review */
div.ytBadgeShapeText, span.ytAttributedStringHost, span.ytmBadgeAndBylineRendererSeparator { max-width: 100% !important; overflow: hidden !important; text-overflow: ellipsis !important; box-sizing: border-box !important; }","backdropHtml":"<div id="batman-rain" style="position:fixed;top:0;left:0;width:100vw;height:100vh;pointer-events:none;z-index:9998;opacity:0.6;overflow:hidden;"><svg width="100%" height="100%" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="rain-streak" x1="0" y1="0" x2="10%" y2="100%"><stop offset="0%" stop-color="rgba(139,0,0,0)"/><stop offset="70%" stop-color="rgba(200,30,30,0.25)"/><stop offset="100%" stop-color="rgba(180,180,200,0.45)"/></linearGradient><pattern id="rain-grid" width="80" height="80" patternUnits="userSpaceOnUse"><line x1="10" y1="0" x2="18" y2="80" stroke="url(#rain-streak)" stroke-width="1.5"/><line x1="45" y1="0" x2="53" y2="80" stroke="url(#rain-streak)" stroke-width="1.2"/><line x1="70" y1="0" x2="78" y2="80" stroke="rgba(139,0,0,0.18)" stroke-width="2"/></pattern></defs><rect width="100%" height="100%" fill="url(#rain-grid)" style="animation:blood-drip 0.8s linear infinite;"/></svg></div>","hudHtml":"","customJs":"try { MydesBridge.enable3DTilt(1.2); } catch(e){}"}

